entries[200587] = { ["name"] = "Leatherbound Expedition Note", ["text"] = "Binds when picked up\n\"The tightly rolled parchment is wrapped in cracked, dyed leather. The initials T.D. are visible across the binding.\"\n<Right Click to Read>\nSell Price:" }
entries[200588] = { ["name"] = "Meaty Stem", ["text"] = "Dragon Isles Supplies\nBinds when picked up\nAdd the Meaty Stem to your Dragon Isles Supplies.\n\"The barbs are a sign of the plant maturing, to protect the high protein flesh of the stem.\"\nSell Price:" }
entries[200589] = { ["name"] = "Hydro Life Seed", ["text"] = "Dragon Isles Supplies\nBinds when picked up\nAdd the Hydro Life Seed to your Dragon Isles Supplies.\n\"Life seeds are cultivated at the Life Pools as planted with another seed they increase its growth tenfold.\"\nSell Price:" }
entries[200590] = { ["name"] = "Carefully Rolled Message", ["text"] = "Binds when picked up\n\"The note's been rolled so tightly it's stiff, retaining its curled nature no matter how hard you try to unfurl it.\"\n<Right Click to Read>\nSell Price:" }
entries[200592] = { ["name"] = "Dirty Old Satchel", ["text"] = "Binds when picked up\nUse: Open the satchel, revealing the contents inside.\n\"A cracked, faded seal of the Dragonscale Expedition appears on the button of the satchel's flap.\"\nSell Price:" }
entries[200593] = { ["name"] = "Sealed Expedition Note", ["text"] = "Binds when picked up\n\"Signed and sealed from the Dragonscale Expedition.\"\n<Right Click to Read>\nSell Price:" }
entries[200594] = { ["name"] = "Thaelin's Second Favorite Comb", ["text"] = "Binds when picked up\n\"Perfect for even the toughest, dwarven beards.\"\n<Right Click to Read>\nSell Price:" }
entries[200595] = { ["name"] = "Odorous Parchment", ["text"] = "Binds when picked up\n\"Whatever was written across the parchment previously appears to have been washed away with water, leaving an odorous smell and watered down lettering behind.\"\n<Right Click to Read>\nSell Price:" }
entries[200596] = { ["name"] = "Letter from Thaelin Darkanvil", ["text"] = "Binds when picked up\n\"The letter is written on fresh parchment and stamped with the seal of the Dragonscale Expedition.\"\n<Right Click to Read>\nSell Price:" }
