entries[200606] = { ["name"] = "Previously Owned Map", ["text"] = "Binds when picked up\n\"Made of animal hide, the map details a once-known location of a treasure, marked with an 'X', now crossed off the list as if it's already been discovered.\"\n<Right Click to Read>\nSell Price:" }
