entries[200613] = { ["name"] = "Aylaag Windstone Fragment", ["text"] = "Binds to Warband\nUnique\nUse: Return to the Aylaag camp, wherever they happen to be. Not available while the clan is moving. (15 Min Cooldown)\n5 Charges\nRequires Renown 11 with the Maruuk Centaur and completing the quest \"Whistling Rocks\".\n\"A small amount of the wind's blessing, just enough to carry a whisper and the whisperer.\"" }
