entries[200617] = { ["name"] = "Shattering Totem", ["text"] = "Binds when picked up\nUnique (20)\nUse: Causes the earth at the target location to tremble and break, dealing Nature damage every 1 sec to enemies in 10 yard radius. Lasts 10 sec.\n\nUsable in the Obsidian Citadel and adjacent lava fields. (8 Sec Cooldown)\n\"A powerful totem created by Earthmender Govrum.\"\nSell Price:" }
