entries[200690] = { ["name"] = "Ritherem Petals", ["text"] = "Dragon Isles Supplies\nBinds when picked up\nAdd the Ritherem Petals to your Dragon Isles Supplies.\n\"Ground into a fine powder the Ritherem Petals act as a natural clotting agent.\"\nSell Price:" }
entries[200691] = { ["name"] = "Claw Thistle Barbs", ["text"] = "Dragon Isles Supplies\nBinds when picked up\nAdd the Claw Thistle Barbs to your Dragon Isles Supplies.\n\"The barb tips have a natural numbing agent that is used by the Maruuk in medical treatments.\"\nSell Price:" }
entries[200692] = { ["name"] = "Gift of the Grove", ["text"] = "Dragon Isles Supplies\nBinds when picked up\nAdd the Gift of the Grove to your Dragon Isles Supplies.\n\"Extracts from the plant can be used to enhance the effectiveness of poultices, reducing the healing time for large cuts and abrasions.\"\nSell Price:" }
entries[200693] = { ["name"] = "Terata Leaves", ["text"] = "Dragon Isles Supplies\nBinds when picked up\nAdd the Terata Leaves to your Dragon Isles Supplies.\n\"The oil in the leaves of the Terata plant can be used to sooth burns.\"\nSell Price:" }
entries[200694] = { ["name"] = "River Bell Bulbs", ["text"] = "Dragon Isles Supplies\nBinds when picked up\nAdd the River Bell Bulbs to your Dragon Isles Supplies.\n\"The rejuvenating waters of the Ohn'ahran River infuse the bulbs with natural minerals, used widely on the plains as vitamins.\"\nSell Price:" }
entries[200695] = { ["name"] = "Fangtooth Petals", ["text"] = "Dragon Isles Supplies\nBinds when picked up\nAdd the Fangtooth Petals to your Dragon Isles Supplies.\n\"Extremely poisonous, the centaur of the plains use a paste made from the flowers petals to poison their arrows for big game hunts.\"\nSell Price:" }
entries[200696] = { ["name"] = "Winter Berries", ["text"] = "Dragon Isles Supplies\nBinds when picked up\nAdd the Winter Berries to your Dragon Isles Supplies.\n\"Thriving in the cold climate of the Azure Span, the berries are high in sugars and traded widely across the Dragon Isles.\"\nSell Price:" }
entries[200697] = { ["name"] = "Blightshroom", ["text"] = "Dragon Isles Supplies\nBinds when picked up\nAdd the Blightshroom to your Dragon Isles Supplies.\n\"Born of blight, this mushroom is poisonous in large quantities, but when steeped in small doses it is a great pain reliever.\"\nSell Price:" }
entries[200698] = { ["name"] = "Ley Orb", ["text"] = "Dragon Isles Supplies\nBinds when picked up\nAdd the Ley Orb to your Dragon Isles Supplies.\n\"When picked near maturity, the orb can be ground into a powder that can produce a dazzling and distracting mist.\"\nSell Price:" }
entries[200699] = { ["name"] = "Milkweed Fibers", ["text"] = "Dragon Isles Supplies\nBinds when picked up\nAdd the Milkweed Fibers to your Dragon Isles Supplies.\n\"Used to line winter clothes and insulating cold weather dwellings.\"\nSell Price:" }
entries[200700] = { ["name"] = "Cuppressa Berries", ["text"] = "Dragon Isles Supplies\nBinds when picked up\nAdd the Cuppressa Berries to your Dragon Isles Supplies.\n\"The oils of the berry like cones are used commonly as a diuretic but can be distilled into a piney alcohol.\"\nSell Price:" }
entries[200701] = { ["name"] = "Titian Extract", ["text"] = "Dragon Isles Supplies\nBinds when picked up\nAdd the Titian Extract to your Dragon Isles Supplies.\n\"The hearty auburn gold pigment is used almost exclusively in Titan architecture and outdoor painting.\"\nSell Price:" }
entries[200702] = { ["name"] = "Magenta Titian Extract", ["text"] = "Dragon Isles Supplies\nBinds when picked up\nAdd the Magenta Titian Extract to your Dragon Isles Supplies.\n\"A variety of the classic Titian Orchid, it must be bred to keep its deep purple hue.\"\nSell Price:" }
