entries[200880] = { ["name"] = "Wind-Sealed Mana Capsule", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+244 Intellect\nEquip: Casting spells and abilities has a low chance to refund 1121 mana. If below 50% mana the seal breaks restoring 16820 mana.\nThe seal can only be broken once every 5 minutes. (1s cooldown)\nSell Price:" }
entries[200882] = { ["name"] = "Big Kinook's Spare Ladle", ["text"] = "Cosmetic\nBinds to Warband\nTwo-Hand Staff\n1 - 2 Damage Speed 3.60\n(0.4 damage per second)\nUse: Add this appearance to your Warband collection.\nSell Price:" }
