entries[200884] = { ["name"] = "Ensemble: Glorious Dragonrider's Mail", ["text"] = "Binds to Warband\nClasses: Hunter , Shaman , Evoker\nUse: Collect the appearances of the Glorious Dragonrider's Mail armor set.\n\"The gold and crimson mark a Drekirjar as a force to be reckoned with.\"" }
entries[200885] = { ["name"] = "Cinna-Cinderbloom Tea", ["text"] = "Binds when picked up\nUnique (20)\nUse: Steeped from Hyjal's sparking flower petals, this brew is sure to put a pep or two in your step. Increases movement speed by 30% for 1 hour.\n\nOnly active while in the Dragon Isles.\nSell Price:" }
entries[200886] = { ["name"] = "Lemon Silverleaf Tea", ["text"] = "Binds to Warband\nUse: Keep yourself feeling prim and proper with this classic brew from the Eastern Kingdoms.\nSell Price:" }
entries[200887] = { ["name"] = "Charred Porter", ["text"] = "Binds when picked up\nUnique (20)\nUse: A loa-blessed mug of charred porter to settle your meal of meats. Increases Primary Stat by 10% for 1 hour.\n\nOnly active while in the Dragon Isles.\nSell Price:" }
entries[200888] = { ["name"] = "Coal-Fired Rib Rack", ["text"] = "Binds when picked up\nUnique (20)\nUse: Roasted over a bed of anchor weed, siren's pollen, and fresh vorquin coal of a hearty flavor that courses through your very being! Increases Stamina by 20% for 1 hour.\n\nOnly active while in the Dragon Isles.\nSell Price:" }
entries[200889] = { ["name"] = "Highly Spiced Haunch", ["text"] = "Binds to Warband\nUse: A delicious direhorn haunch dry-rubbed with generous helpings of ground Akunda's Bite fills your belly! You suddenly feel like a mighty warrior!\nSell Price:" }
entries[200890] = { ["name"] = "Stonetalon Bloom Skewer", ["text"] = "Binds when picked up\nUnique (20)\nUse: A skewer of lightly grilled and freshly seasoned vegetables straight from the Bloodhoof farms of Kalimdor. Increases mana regen by 30% for 1 hour.\n\nOnly active while in the Dragon Isles.\nSell Price:" }
entries[200891] = { ["name"] = "Druidic Dreamsalad", ["text"] = "Binds to Warband\nUse: Nighthaven berries over a bed of spirit-enhancing greens, filling you with the glory of growing life wherever you roam!\nSell Price:" }
entries[200892] = { ["name"] = "Dragonfruit Punch", ["text"] = "Binds when picked up\nUnique (20)\nUse: Kick back and relax with a cup of the finest Dragon Isles fruits and berries this side of the Cascades. Reduces fall speed.\n\nOnly active while in the Dragon Isles.\nSell Price:" }
entries[200893] = { ["name"] = "Azsunian Poached Lobster", ["text"] = "Binds when picked up\nUnique (20)\nUse: Bold, Nor'danil lobster brined & poached in the traditional Broken Isles method. Increases all stats by 5% for 1 hour.\n\nOnly active while in the Dragon Isles.\nSell Price:" }
entries[200894] = { ["name"] = "Rare Vintage Arcwine", ["text"] = "Binds when picked up\nUnique (20)\nUse: The sweet, tannic notes of this arcwine sing of Suramar while sharpening your senses. Increases critical damage by 30% for 1 hour.\n\nOnly active while in the Dragon Isles.\nSell Price:" }
entries[200895] = { ["name"] = "Fine Taladorian Cheese Platter", ["text"] = "Binds to Warband\nUse: From the milks of draenei-farmed, orchid-fed talbuk, clefthoof, and elekks, a wondrously pungent array of fine aged cheeses fills the air!\nSell Price:" }
entries[200896] = { ["name"] = "Captain's Caramelized Catfish", ["text"] = "Binds when picked up\nUnique (20)\nUse: Crispy baked Bridgeport catfish fit for a Proudmoore. Increases armor by 30% for 1 hour.\n\nOnly active while in the Dragon Isles.\nSell Price:" }
entries[200897] = { ["name"] = "Venrik's Goat Milk", ["text"] = "Binds to Warband\nUse: Even without the traditional skull mug, this makes you feel like a real Freehold pirate!\nSell Price:" }
entries[200898] = { ["name"] = "Mantis Shrimp Cocktail", ["text"] = "Binds when picked up\nUnique (20)\nUse: Lemon-brined Mantis Shrimp from Binan Village, dipped in tangy cindergut sauce. Grants water breathing.\n\nOnly active while in the Dragon Isles.\nSell Price:" }
entries[200899] = { ["name"] = "Seared Sea Mist Noodles", ["text"] = "Binds when picked up\nUnique (20)\nUse: Hot Sea Mist noodles straight from the pan garnished with cute cubed Paw'don roots and vegetables. Increases haste by 10% for 1 hour.\n\nOnly active while in the Dragon Isles.\nSell Price:" }
