entries[201398] = { ["name"] = "Mogu Mozzarella", ["text"] = "Use: Restores ( 70313 / 5 * 20) health over 20 sec.\nMust remain seated while eating.\n\"Hailing from before the Pandaren Revolution, this cheese was a key component of an ancient Mogu favorite, Stuffed Lushrooms.\"\nSell Price:" }
