entries[201411] = { ["name"] = "Ancient Vault Artifact", ["text"] = "Binds when picked up\n\"This artifact appears to date back to the time of the Incarnates. Lillian Brightmoon of the Dragonscale Expedition would be interested in this item.\"" }
