entries[201413] = { ["name"] = "Eternity-Infused Burrata", ["text"] = "Use: Restores ( 45000 / 5 * 20) health and ( 60000 / 5 * 20) mana over 20 sec. Must remain seated while eating.\n\"Infused with water from the Well of Eternity itself, this treat was once highly prized amongst the Kaldorei. Prior to the Sundering, of course.\"\nSell Price:" }
entries[201414] = { ["name"] = "Qalashi Wingshredder", ["text"] = "Binds when picked up\nUse: Dismounts an enemy airborne player. Can only be used while within War Mode in the Dragon Isles. (1 Min Cooldown)" }
entries[201415] = { ["name"] = "Temporal Parmesan", ["text"] = "Use: Restores ( 70313 / 5 * 20) health over 20 sec.\nMust remain seated while eating.\n\"Untethered from time, this Parmesan has a nifty habit of materalizing on your pasta ahead of schedule.\"\nSell Price:" }
entries[201416] = { ["name"] = "Black Empire Brunost", ["text"] = "Use: Restores ( 70313 / 5 * 20) health over 20 sec.\nMust remain seated while eating.\n\"If you hold this foul-smelling cheese up to your ear, you can hear a strange whispering. Plus, it's high in fat.\"\nSell Price:" }
entries[201417] = { ["name"] = "Curding of Stratholme", ["text"] = "Use: Restores ( 70313 / 5 * 20) health over 20 sec.\nMust remain seated while eating.\n\"This entire dairy must be purged! It's the only whey.\"\nSell Price:" }
