entries[201419] = { ["name"] = "Apexis Asiago", ["text"] = "Use: Restores ( 45000 / 5 * 20) health and ( 60000 / 5 * 20) mana over 20 sec. Must remain seated while eating.\n\"Perfected by Anhari and Skalaxi scholars, the Apexis crystal containing this cheese's recipe has long since been lost.\"\nSell Price:" }
entries[201420] = { ["name"] = "Gnolan's House Special", ["text"] = "Use: Restores ( 45000 / 5 * 20) health and ( 60000 / 5 * 20) mana over 20 sec. Must remain seated while eating.\n\"Meaty and surprisingly well seasoned, with just a hint of cartilaginous crunch.\"\nSell Price:" }
