entries[201425] = { ["name"] = "Yellow War Ottuk", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 30 with the Iskaara Tuskarr.\n\n\"The yellow ottuks of the Azure Span are sleek, sneaky, and smart. Those trained for war are the finest tuskarr cavalry mounts, equally capable on the ground and in the waters.\"\nFaction:\nIskaara Tuskarr\nRenown:\n30\nVendor:\nTatto\nLocation:\nIskaara\nCost:\n5\n5\n1000" }
entries[201426] = { ["name"] = "Brown War Ottuk", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 30 with the Iskaara Tuskarr.\n\n\"The tuskarr of Iskaara are loathe to war against anyone, but many tuskarr and their allies have nonetheless taken up the spear with a war ottuk beside them.\"\nFaction:\nIskaara Tuskarr\nRenown:\n30\nVendor:\nTatto\nLocation:\nIskaara\nCost:\n5\n5\n1000" }
entries[201427] = { ["name"] = "Fleeting Sands", ["text"] = "Binds when picked up\nUnique (20)\nUse: A sprinkle of temporal magic to get you going!\n\nIncreases movement speed by 250% for 5 sec. (30 Sec Cooldown)\nSell Price:" }
entries[201428] = { ["name"] = "Quicksilver Sands", ["text"] = "Unique (20)\nUse: This sand will let you borrow time, but take it back after.\n\nIncreases movement speed by 200% for 10 sec, then reduces movement speed by 90% for 10 sec. (1 Min Cooldown)\nSell Price:" }
